    $sectors = get_mega_sectors();
    $sub_focus = [["Foundations, Daily Protocols & Practical Step-by-Step Guide", "الأسس العلمية والخطوات التطبيقية اليومية خطوة بخطوة"], ["Advanced Techniques, Professional Standards & Best Practices", "المهارات المتقدمة والمعايير الاحترافية وأفضل الممارسات"], ["Diagnostic Checklists, Troubleshooting & Quality Solutions", "قوائم الفحص العملي وحل المشكلات وضمان أعلى جودة"], ["Modern Innovations, Smart Tools & Sustainable Mastery", "الأدوات الحديثة والابتكارات الذكية والإتقان المستدام"]];
    $data = [];
    $did = 1;
    foreach ($sectors as $sec) {
        foreach ($sec['base_topics'] as $bt) {
            $base_en = $bt[0];
            $base_ar = $bt[1];
            foreach ($sub_focus as $sf) {
                $data[] = [
                    "discipline_id" => $did++,
